// src/screens/MediaScreen.js - экран для работы с мультимедиа
import React, { useState, useRef } from 'react';
import { 
  View, 
  Text, 
  TouchableOpacity, 
  StyleSheet, 
  ScrollView,
  Image,
  Alert,
  Platform 
} from 'react-native';
import { Audio } from 'expo-av';
import * as ImagePicker from 'expo-image-picker';
import useStorage from '../hooks/useStorage'; // 🚀 Добавлен импорт для чтения темы

const MediaScreen = () => {
  // 🚀 Читаем настройки для определения темы
  const { value: appSettings } = useStorage('appSettings', { darkMode: false });
  const isDarkMode = appSettings?.darkMode ?? false;

  const [sound, setSound] = useState();
  const [recording, setRecording] = useState();
  const [recordedURI, setRecordedURI] = useState();
  const [image, setImage] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);

  const soundRef = useRef();

  const LOCAL_SOUND_URI = require('../../assets/mixkit-modern-technology-select-3124.wav');

  const playSoundEffect = async (uri) => { 
    try {
        const { sound } = await Audio.Sound.createAsync(uri, { shouldPlay: true });

        sound.setOnPlaybackStatusUpdate((status) => {
            if (status.didJustFinish) {
                sound.unloadAsync();
            }
        });
    } catch (error) {
        console.warn('Ошибка воспроизведения звукового эффекта:', error);
    }
  };

  const playSound = async () => { /* ... */ };
  const stopSound = async () => { /* ... */ };
  const startRecording = async () => { /* ... */ };
  const stopRecording = async () => { /* ... */ };
  const playRecordedSound = async () => { /* ... */ };
  const pickImage = async (fromCamera = false) => { /* ... */ };


  const themeStyles = getStyles(isDarkMode);

  return (
    <ScrollView style={themeStyles.container}>

      {/* Секция Изображения */}
      <View style={themeStyles.section}>
        <Text style={themeStyles.sectionTitle}>Изображения</Text>
        <View style={styles.buttonRow}>
          <TouchableOpacity 
            style={[styles.button, styles.photoButton]} 
            onPress={() => pickImage(false)}
          >
            <Text style={styles.buttonText}>Выбрать из Галереи</Text>
          </TouchableOpacity>
          <TouchableOpacity 
            style={[styles.button, styles.photoButton]} 
            onPress={() => pickImage(true)}
          >
            <Text style={styles.buttonText}>Сделать Фото</Text>
          </TouchableOpacity>
        </View>
        {/* Отображение изображения */}
        {image && <Image source={{ uri: image }} style={styles.image} />}
      </View>

      {/* Секция Аудио */}
      <View style={themeStyles.section}>
        <Text style={themeStyles.sectionTitle}>Аудио</Text>

        <TouchableOpacity 
          onPress={playSound} 
          disabled={isPlaying} 
          style={[styles.button, styles.audioButton]}
        >
          <Text style={styles.buttonText}>
            {isPlaying ? 'Воспроизведение...' : 'Воспроизвести Тест. Звук'}
          </Text>
        </TouchableOpacity>

        <TouchableOpacity 
          onPress={recording ? stopRecording : startRecording} 
          style={[styles.button, recording ? styles.stopButton : styles.recordButton]}
        >
          <Text style={styles.buttonText}>
            {recording ? 'Остановить Запись' : 'Начать Запись Голоса'}
          </Text>
        </TouchableOpacity>

        {recordedURI && (
            <TouchableOpacity 
                onPress={playRecordedSound} 
                style={[styles.button, styles.playRecordedButton]}
            >
                <Text style={styles.buttonText}>
                    Воспроизвести Запись
                </Text>
            </TouchableOpacity>
        )}
      </View>

    </ScrollView>
  );
};

// 🚀 Функция для динамических стилей
const getStyles = (isDarkMode) => StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: isDarkMode ? '#121212' : '#f5f5f5',
    padding: 20,
  },
  section: {
    backgroundColor: isDarkMode ? '#1e1e1e' : 'white',
    padding: 15,
    borderRadius: 10,
    marginBottom: 15,
    shadowColor: isDarkMode ? '#000' : '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: isDarkMode ? 0.3 : 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  sectionTitle: {
    fontSize: 20,
    fontWeight: 'bold',
    marginBottom: 15,
    color: isDarkMode ? '#eee' : '#333',
  },
});

// 🚀 Статические стили
const styles = StyleSheet.create({
  buttonRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 5,
  },
  button: {
    paddingHorizontal: 15,
    paddingVertical: 12,
    borderRadius: 8,
    alignItems: 'center',
    marginVertical: 5,
    flex: 1,
    marginHorizontal: 5,
  },
  photoButton: {
    backgroundColor: '#34C759',
  },
  audioButton: {
    backgroundColor: '#5856D6',
  },
  recordButton: {
    backgroundColor: '#FF3B30',
  },
  stopButton: {
    backgroundColor: '#FFCC00',
  },
  playRecordedButton: {
      backgroundColor: '#007AFF',
      marginHorizontal: 5,
  },
  buttonText: {
    color: 'white',
    fontSize: 16,
    fontWeight: '600',
  },
  image: {
    width: '100%',
    height: 200,
    borderRadius: 8,
    marginTop: 15,
    resizeMode: 'cover',
    borderWidth: 1,
    borderColor: '#eee',
  },
});

export default MediaScreen;
